/**
 * Samhälle → Ekonomi & arbetsliv → Arbetsplatsens vardag, 1511–1517: tasks and responsibility, working
 * hours and schedules, meetings and work teams, the working environment and safety, feedback and
 * appraisal talks, holidays and leave, and conflicts at work. Most words are abstract, so the pictures
 * are small symbolic scenes built from a few recurring signs: a clock with a coloured arc (working
 * time), a week strip of five weekday cells (how much one works), a white sheet (a document), a chef
 * in a navy jacket with a red tie, a worker in a yellow helmet, the green-cross badge of the safety
 * representative, the sun (holiday), the moon (night), green and red marks, and a grey reference where
 * a contrast helps. No words in the pictures and no pointing fingers.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, star, type Svg } from './kit';
import { type Build } from './figures';
import { HL, T, arm } from './people';
import { P as F, type Mood, greyed } from './blindFix';
import { checkIcon } from './labelIcons';

// ── Geometry ─────────────────────────────────────────────────────────
const RED = '#e8302c';
const NIGHT = '#2c3560';
const SAFE = '#3fae5a';
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
/** Head and shoulder positions of a standing figure (figures.ts) at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, ty, hy: ty - 56 * s, hr: 10 * s, sy: ty - 38 * s, sl: x - 13 * s, sr: x + 13 * s }; };
const hnd = (x: number, y: number, r = 3) => circle(x, y, r, C.skin, C.ink, 1.2);
/** An arm that starts at the shoulder (side −1 = picture-left, 1 = picture-right) and ends in a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q0 = geo(x, h); return all(arm(side < 0 ? q0.sl : q0.sr, q0.sy, tx, ty), hnd(tx, ty, 3 * Math.max(0.7, h))); };
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Build> = {}) => F({ x, top, mood, ...more });
/** Draw in the local coordinates of the standing figure at x (head centre 0,−56; torso −42…2; feet at 49). */
const on = (x: number, h: number, ...k: Svg[]) => { const s = 0.84 * h; return g(`translate(${x} ${f1(112 - 49 * s)}) scale(${s.toFixed(3)})`, ...k); };
const helmetL = (col: string = C.yellow) => all(path('M-11 -60 C-11 -75 11 -75 11 -60 Z', col, C.ink, 1.6), rect(-13.5, -62, 27, 3.4, col, 1.5, C.ink, 1.4));
const vestL = (col: string = C.reflex) => all(path('M-13.5 -41 L-6 -41 L0 -28 L6 -41 L13.5 -41 L12 1 L-12 1 Z', col, C.ink, 1.4), line('M-12.6 -14 L-3 -14 M3 -14 L12.6 -14', C.silver, 2.4));
const tieL = all(path('M-6 -42 L0 -34 L6 -42', 'none', C.white, 2.4), path('M-1.8 -38 L1.8 -38 L3 -24 L0 -20 L-3 -24 Z', RED, C.ink, 0.9));
const badgeL = all(line('M-6 -41 L0 -26 L6 -41', C.denim, 1.2), rect(-4, -26, 8, 10, C.white, 1.5, C.ink, 1), rect(-2.6, -24.5, 5.2, 3, C.sky, 0.5, null));
/** The safety representative's sign: a green cross on a white disc (on the chest). */
const safeBadgeL = all(circle(-5, -30, 5.2, C.white, C.ink, 1.1), rect(-6.2, -33.6, 2.4, 7.2, SAFE, 0.3, null), rect(-8.6, -31.2, 7.2, 2.4, SAFE, 0.3, null));
/** Small head-and-shoulders person, e.g. seated behind a table; mood smile | frown | flat. */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' = 'smile', s = 1, grey = false) => { const sk = grey ? C.grey2 : C.skin, hr = grey ? C.grey : C.hair, c = grey ? C.grey : col; return g(`translate(${x} ${y}) scale(${s})`, path('M-10 16 C-10 4 10 4 10 16 Z', c, C.ink, 1.4), circle(0, -6, 7.5, sk, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', hr, null),
  all(circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null)),
  mood === 'smile' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1)); };
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; }
  else { const e = ty > cy ? B : Tp, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, C.ink, 1.5), rect(L, Tp, w, h, fill, 6, C.ink, 1.5), path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, null), inner);
};
/** Bubble beside the head of the figure at x (side 1 = right of the head, −1 = left); f draws the content at the bubble centre. */
const sb = (x: number, h: number, side: 1 | -1, w: number, hh: number, f: (cx: number, cy: number) => Svg, dy = 0, fill: string = C.white) => { const k = geo(x, h), cx = x + side * (k.hr + 6 + w / 2), cy = k.hy - 8 + dy; return say(cx, cy, w, hh, x + side * (k.hr + 1), k.hy, f(cx, cy), fill); };

// ── Marks ────────────────────────────────────────────────────────────
const q = (x: number, y: number, sz = 13, col: string = C.navy) => T(x, y + sz * 0.36, '?', sz, col);
const ex = (x: number, y: number, sz = 13, col: string = HL) => T(x, y + sz * 0.36, '!', sz, col);
const num = (x: number, y: number, s: string, sz = 10, col: string = C.ink) => T(x, y + sz * 0.36, s, sz, col);
const para = (x: number, y: number, sz = 14, col: string = C.navy) => T(x, y + sz * 0.36, '§', sz, col);
const cross = (x: number, y: number, s = 1, col: string = RED) => line(`M${x - 5 * s} ${y - 5 * s} L${x + 5 * s} ${y + 5 * s} M${x + 5 * s} ${y - 5 * s} L${x - 5 * s} ${y + 5 * s}`, col, 2.4 * s);
const check = (x: number, y: number, s = 1, col: string = C.green) => checkIcon(x, y, s, col);
const okB = (x: number, y: number, r = 8) => all(circle(x, y, r, C.green, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.22));
const noB = (x: number, y: number, r = 8) => all(circle(x, y, r, RED, C.ink, 1.2), line(`M${f1(x - r * 0.4)} ${f1(y - r * 0.4)} L${f1(x + r * 0.4)} ${f1(y + r * 0.4)} M${f1(x + r * 0.4)} ${f1(y - r * 0.4)} L${f1(x - r * 0.4)} ${f1(y + r * 0.4)}`, C.white, r * 0.22));
const ring = (x: number, y: number, r: number, col: string = HL) => circle(x, y, r, 'none', col, 2.4);
const thumb = (x: number, y: number, s = 1, up = true, col: string = C.skin) => g(`translate(${x} ${y}) scale(${s}${up ? '' : ' -1'})`, rect(-6, -2, 11, 11, col, 3, C.ink, 1.2), path('M-4 -2 L-3 -10 C-3 -13 1 -13 1 -10 L1 -2 Z', col, C.ink, 1.2), line('M-1 3 L5 3 M-1 6 L5 6', C.ink, 0.7));
const zz = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, T(0, 0, 'z', 9, C.navy), T(6, -6, 'z', 7, C.navy), T(11, -11, 'z', 5, C.navy));
const strain = (x: number, y: number) => line(`M${x - 6} ${y - 4} L${x - 10} ${y - 8} M${x} ${y - 6} L${x} ${y - 11} M${x + 6} ${y - 4} L${x + 10} ${y - 8}`, HL, 1.8);
const bolt = (x: number, y: number, s = 1, col: string = C.yellow) => g(`translate(${x} ${y}) scale(${s})`, path('M2 -12 L-7 2 L-1 2 L-4 13 L7 -3 L1 -3 Z', col, C.ink, 1.3));
const jag = (x1: number, x2: number, y: number, col: string = RED) => { let d = `M${x1} ${y}`; const n = 6, w = (x2 - x1) / n; for (let i = 1; i <= n; i++) d += ` L${f1(x1 + i * w)} ${y + (i % 2 ? -5 : 5)}`; return line(d, col, 2.2); };

// ── Things ───────────────────────────────────────────────────────────
const lines = (x: number, y: number, w: number, n = 3, col: string = C.grey) => all(...Array.from({ length: n }, (_, i) => line(`M${x - w / 2} ${y + i * 4.4} L${x + w / 2 - (i === n - 1 ? w * 0.35 : 0)} ${y + i * 4.4}`, col, 1.6)));
/** A sheet of paper; `marks` in the sheet's own coordinates (−14…14, −18…18). */
const doc = (x: number, y: number, s = 1, marks: Svg = '', n = 5, col: string = C.grey2, fill: string = C.white) => g(`translate(${x} ${y}) scale(${s})`, rect(-14, -18, 28, 36, fill, 2, C.ink, 1.6), ...Array.from({ length: n }, (_, i) => line(`M-9 ${-11 + i * 6} L9 ${-11 + i * 6}`, col, 2)), marks);
const box = (x: number, y: number, w = 20, h = 16, col: string = C.tan) => all(rect(x - w / 2, y - h / 2, w, h, col, 1, C.ink, 1.5), line(`M${x - w / 2} ${y - h / 2 + 4} L${x + w / 2} ${y - h / 2 + 4} M${x} ${y - h / 2} L${x} ${y - h / 2 + 4}`, C.brown, 1.1));
const desk = (y: number, x1: number, x2: number) => all(rect(x1, y, x2 - x1, 5, C.tan, 2, C.ink, 1.6), line(`M${x1 + 6} ${y + 5} L${x1 + 6} 112 M${x2 - 6} ${y + 5} L${x2 - 6} 112`, C.brown, 2.6));
const screen = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-14, -11, 28, 19, C.dark, 2, C.ink, 1.4), rect(-12, -9, 24, 15, '#bfe3f5', 1, null), inner, rect(-2, 8, 4, 4, C.dark, 0.5, null), rect(-7, 12, 14, 2.4, C.dark, 1, null));
const phone = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-8 -3 C-8 -9 8 -9 8 -3 L5 -1 L3 -4 L-3 -4 L-5 -1 Z', C.dark, C.ink, 1.1), rect(-7, 0, 14, 7, C.dark, 2, C.ink, 1.1), circle(0, 3.5, 1.8, C.grey2, null));
const envelope = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -7, 20, 14, C.white, 1.5, C.ink, 1.3), path('M-10 -7 L0 1 L10 -7', 'none', C.ink, 1.1));
const clip = (x: number, y: number, s = 1, marks: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-12, -16, 24, 32, C.brown, 2, C.ink, 1.4), rect(-10, -13, 20, 27, C.white, 1, null), rect(-5, -18, 10, 5, C.silver, 1.5, C.ink, 1), marks);
const shelf = (x: number, y: number, w: number) => all(rect(x, y, w, 3, C.brown, 1, C.ink, 1.2));
const plant = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-6 0 L6 0 L4 10 L-4 10 Z', C.orange, C.ink, 1.2), path('M0 0 C-10 -6 -8 -14 -2 -12 C0 -18 6 -16 4 -10 C10 -10 8 -2 0 0 Z', C.green, C.ink, 1.2));
const lamp = (x: number, y: number) => all(line(`M${x} ${y} L${x} ${y + 8}`, C.ink, 1.2), path(`M${x - 7} ${y + 14} L${x - 4} ${y + 8} L${x + 4} ${y + 8} L${x + 7} ${y + 14} Z`, C.yellow, C.ink, 1.2), path(`M${x - 12} ${y + 30} L${x - 7} ${y + 14} L${x + 7} ${y + 14} L${x + 12} ${y + 30} Z`, 'rgba(242,193,78,0.25)', null));
const moon = (x: number, y: number, r = 8, col: string = '#f3e39a') => path(`M${x} ${y - r} A${r} ${r} 0 1 0 ${x} ${y + r} A${f1(r * 0.55)} ${r} 0 1 1 ${x} ${y - r} Z`, col, C.ink, 1.2);
const sunR = (x: number, y: number, r = 7) => all(...Array.from({ length: 8 }, (_, i) => { const a = (i / 8) * Math.PI * 2; return line(`M${f1(x + Math.cos(a) * (r + 3))} ${f1(y + Math.sin(a) * (r + 3))} L${f1(x + Math.cos(a) * (r + 6))} ${f1(y + Math.sin(a) * (r + 6))}`, C.gold, 2); }), circle(x, y, r, C.yellow, C.ink, 1.4));
const sunUp = (x: number, y: number, r = 7) => all(path(`M${x - r} ${y} A${r} ${r} 0 0 1 ${x + r} ${y} Z`, C.yellow, C.ink, 1.3), ...[-60, -30, 0, 30, 60].map((d) => { const a = ((d - 90) * Math.PI) / 180; return line(`M${f1(x + Math.cos(a) * (r + 2.5))} ${f1(y + Math.sin(a) * (r + 2.5))} L${f1(x + Math.cos(a) * (r + 5.5))} ${f1(y + Math.sin(a) * (r + 5.5))}`, C.gold, 1.8); }), line(`M${x - r - 4} ${y} L${x + r + 4} ${y}`, C.ink, 1.2));
/** A clock face; hours h:m; arc = [fromHour, toHour, colour] painted as a sector on the 12-hour dial. */
const clock = (x: number, y: number, r: number, h: number, m = 0, arc?: [number, number, string]) => {
  const pt = (hr: number, rr: number) => { const a = (hr / 12) * Math.PI * 2 - Math.PI / 2; return [x + Math.cos(a) * rr, y + Math.sin(a) * rr] as const; };
  let sec = '';
  if (arc) { const [a0, a1, col] = arc, p0 = pt(a0, r - 1), p1 = pt(a1, r - 1), large = ((a1 - a0 + 12) % 12) > 6 ? 1 : 0; sec = path(`M${x} ${y} L${f1(p0[0])} ${f1(p0[1])} A${r - 1} ${r - 1} 0 ${large} 1 ${f1(p1[0])} ${f1(p1[1])} Z`, col, null); }
  const ticks = Array.from({ length: 12 }, (_, i) => { const a = pt(i, r * 0.82), b = pt(i, r * 0.95); return line(`M${f1(a[0])} ${f1(a[1])} L${f1(b[0])} ${f1(b[1])}`, C.ink, i % 3 ? 0.9 : 1.6); });
  const hh = pt(h + m / 60, r * 0.5), mm = pt(m / 5, r * 0.78);
  return all(circle(x, y, r, C.white, C.ink, 1.8), sec, ...ticks, line(`M${x} ${y} L${f1(hh[0])} ${f1(hh[1])}`, C.ink, 2.2), line(`M${x} ${y} L${f1(mm[0])} ${f1(mm[1])}`, C.ink, 1.4), circle(x, y, 1.6, C.ink, null));
};
/** A week strip of five weekday cells (Mon–Fri) and optionally two weekend cells; fill[i] = 0…1 of the cell filled with col. */
const week = (x: number, y: number, fill: number[], col: string = C.denim, cw = 14, ch = 22, weekend = false) => all(...fill.map((f, i) => all(rect(x + i * (cw + 3), y, cw, ch, C.white, 2, C.ink, 1.2), f > 0 ? rect(x + i * (cw + 3) + 1, y + ch - (ch - 2) * f - 1, cw - 2, (ch - 2) * f, col, 1.5, null) : '')), weekend ? all(rect(x + 5 * (cw + 3), y, cw, ch, '#f6d4d4', 2, C.ink, 1.2), rect(x + 6 * (cw + 3), y, cw, ch, '#f6d4d4', 2, C.ink, 1.2)) : '');
/** A month calendar sheet: 5 rows × 7 columns; `hi` maps cell index → colour, `icon` draws in a cell (cx, cy). */
const month = (x: number, y: number, w: number, hi: Record<number, string> = {}, icon?: (i: number, cx: number, cy: number) => Svg) => { const cw = w / 7, top = 9; return all(rect(x, y, w, top + cw * 5 + 3, C.white, 2, C.ink, 1.4), rect(x, y, w, top, RED, 2, C.ink, 1.4), ...Array.from({ length: 35 }, (_, i) => { const cx = x + (i % 7) * cw + cw / 2, cy = y + top + 2 + Math.floor(i / 7) * cw + cw / 2; return all(rect(cx - cw / 2 + 1, cy - cw / 2 + 1, cw - 2, cw - 2, hi[i] ?? ((i % 7) > 4 ? '#f6d4d4' : C.grey2), 1, null), icon ? icon(i, cx, cy) : ''); })); };
const suitcase = (x: number, y: number, col: string = RED) => all(rect(x - 10, y - 9, 20, 18, col, 3, C.ink, 1.5), path(`M${x - 4} ${y - 9} L${x - 4} ${y - 13} L${x + 4} ${y - 13} L${x + 4} ${y - 9}`, 'none', C.ink, 1.5), line(`M${x - 10} ${y - 2} L${x + 10} ${y - 2}`, C.ink, 1));
const bedL = (x: number, y: number, w: number, col: string = C.sky, face: Svg = '') => all(rect(x, y + 10, w, 9, C.brown, 2, C.ink, 1.6), line(`M${x + 4} ${y + 19} L${x + 4} 112 M${x + w - 4} ${y + 19} L${x + w - 4} 112`, C.brown, 3), rect(x + 2, y, 16, 12, C.white, 5, C.ink, 1.3), circle(x + 12, y + 1, 7, C.skin, C.ink, 1.3), path(`M${x + 5} ${y} C${x + 5} ${y - 8} ${x + 19} ${y - 8} ${x + 19} ${y} C${x + 15} ${y - 3} ${x + 9} ${y - 3} ${x + 5} ${y} Z`, C.hair, null), face, path(`M${x + 18} ${y + 4} C${x + 30} ${y - 2} ${x + w - 8} ${y} ${x + w} ${y + 4} L${x + w} ${y + 11} L${x + 18} ${y + 11} Z`, col, C.ink, 1.5));
const sleepyFace = (x: number, y: number) => all(line(`M${x - 4} ${y} L${x - 1} ${y} M${x + 1} ${y} L${x + 4} ${y}`, C.ink, 1.1));
const thermo = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-2.4, -14, 4.8, 18, C.white, 2.4, C.ink, 1.1), circle(0, 6, 4, RED, C.ink, 1.1), rect(-1, -6, 2, 10, RED, 0.5, null));
const lawBook = (x: number, y: number, s = 1, mark: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-13, -16, 26, 32, '#8a2b2b', 2, C.ink, 1.6), rect(-13, -16, 5, 32, '#5e1c1c', 1, null), line('M-6 -11 L9 -11 M-6 11 L9 11', C.gold, 2), mark, rect(11, -14, 3, 28, '#f3ead6', 0.5, C.ink, 0.8));
const coin = (x: number, y: number, r = 5) => all(circle(x, y, r, C.gold, C.ink, 1.2), circle(x, y, r * 0.55, 'none', '#b88a20', 1));
const office = (x: number, y: number, s = 1, col: string = '#cfd8e2') => g(`translate(${x} ${y}) scale(${s})`, rect(-22, -30, 44, 52, col, 1.5, C.ink, 1.4), ...Array.from({ length: 12 }, (_, i) => rect(-17 + (i % 4) * 9.4, -25 + Math.floor(i / 4) * 11, 6, 7, '#9ad0f0', 0.5, C.ink, 0.6)), rect(-5, 9, 10, 13, C.brown, 0.5, C.ink, 1));
const factory = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-26 20 L-26 -4 L-14 -12 L-14 -4 L-2 -12 L-2 -4 L10 -12 L10 -4 L26 -4 L26 20 Z', '#d9c7a8', C.ink, 1.4), rect(14, -24, 7, 20, C.grey, 1, C.ink, 1.2), ...[-18, -6, 6, 18].map((cx) => rect(cx - 3, 4, 6, 6, '#9ad0f0', 0.5, C.ink, 0.6)));
const ladder = (x: number, y: number, h: number, broken = false) => all(line(`M${x - 6} ${y} L${x - 6} ${y + h} M${x + 6} ${y} L${x + 6} ${y + h}`, C.brown, 2.4), ...Array.from({ length: Math.floor(h / 9) }, (_, i) => (broken && i === 2 ? line(`M${x - 6} ${y + 5 + i * 9} L${x - 1} ${y + 8 + i * 9}`, C.brown, 2) : line(`M${x - 6} ${y + 5 + i * 9} L${x + 6} ${y + 5 + i * 9}`, C.brown, 2))));
const goggles = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-24 -2 C-34 -4 -34 -10 -24 -10', 'none', C.dark, 2.4), path('M24 -2 C34 -4 34 -10 24 -10', 'none', C.dark, 2.4), path('M-24 -12 C-24 -16 24 -16 24 -12 L24 6 C24 10 6 10 3 4 C1 1 -1 1 -3 4 C-6 10 -24 10 -24 6 Z', 'rgba(170,220,245,0.75)', C.ink, 2), path('M-24 -12 C-24 -16 24 -16 24 -12 L24 -8 L-24 -8 Z', C.orange, C.ink, 1.4), line('M-16 -3 L-10 2 M10 -3 L16 2', C.white, 2));
const earMuffs = (x: number, y: number, s = 1, col: string = RED) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 2 C-12 -16 12 -16 12 2', 'none', C.dark, 3), rect(-17, -2, 9, 13, col, 4, C.ink, 1.3), rect(8, -2, 9, 13, col, 4, C.ink, 1.3));
const glove = (x: number, y: number, s = 1, col: string = C.orange) => g(`translate(${x} ${y}) scale(${s})`, path('M-6 8 L-6 -4 L-7 -12 C-7 -14 -4 -14 -4 -12 L-3 -6 L-3 -14 C-3 -16 0 -16 0 -14 L0 -6 L1 -13 C1 -15 4 -15 4 -13 L3 -5 L5 -10 C6 -12 8 -11 8 -9 L5 2 L5 8 Z', col, C.ink, 1.2));
const boot = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-6 -12 L4 -12 L4 2 L12 4 C14 5 14 9 12 9 L-6 9 Z', C.dark, C.ink, 1.3), rect(-6, 5, 20, 4, C.yellow, 1, C.ink, 1));
